#!/usr/bin/env python3
"""Turn 35 Wave 76: THE FACILITY LADDER, CONFIRMED AND RANKED - the uniform 75 x N cost from a
second source, the Medical and Commercial per-level effects, the Commercial nerf history, the
six-facility priority order, the Fanzone's level count, and the F2P COIN cost of maxing a player.

Wave 76's most valuable finding is the coin cost of a maxed player: ~32,000 coins via Common
coaches or ~30,000 via Rare, bought and released. That is the number that decides whether a
free-to-play player maxes one star or farms facilities.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w76')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_fac=new_ev("r/DreamLeagueSoccer zfrglq (8 Dec 2022, the 75/150/225/300/375 facility ladder), 1b2xxys (29 Feb 2024, the Training facility guide with the same prices), 1h6nprr (4 Dec 2024, the Accommodation ladder and the 4,125-gem total), 1h6vtqe (5 Dec 2024, the special-coach efficiency, the ~5,000-gem Accommodation estimate and the 64-player cap), 1b8eain (6 Mar 2024, the six-facility priority list, the Commercial nerf and the rust effect), omqcz8 (18 Jul 2021, the 40-50 coin maxed-Commercial figure), 11on7r4 (11 Mar 2023, the coin cost to max a player), 1rs93dn (13 Mar 2026, the Spanish facility advice and the Recruitment Centre's function), 1ceqwgc (27 Apr 2024, the gem-to-facility list), 13twf9y (28 May 2023, the facility advice), LevelWinner DLS20/21/22 facility guides (the Medical and Commercial per-level effects), sportsdunia DLS26 coins guide (30 Dec 2025, the Commercial table), bluestacks DLS26 guides (the facility functions), gtrmod (23 Jun 2026, the Fanzone at level 5), fifaworldcupnews (23 Jul 2026, the Facilities Empire), dlskits.mobi (28 Aug 2026, the facility list)",
    "THE FACILITY LADDER, CONFIRMED AND RANKED, PLUS THE F2P COIN COST OF A MAXED PLAYER. (1) THE UNIFORM 75 x N FACILITY COST LADDER, CONFIRMED BY A SECOND INDEPENDENT SOURCE: 'For each facility, the costs for 1-5 stars are 75 / 150 / 225 / 300 / 375 diamonds, hence 1125 diamonds in total' (zfrglq), and the Training Facility Guide lists the identical ladder - 'LEVEL 1 PRICE: 75, LEVEL 2: PRICE 150, LEVEL 3: PRICE 225, LEVEL 4: PRICE 300, LEVEL 5: PRICE 375'. So five facilities at 1,125 gems each, with Accommodation running to TEN levels (75, 150, 225, 300, 375, 450, 525, 600, 675, 750 = 4,125) because it is the only one with more than five levels. (2) THE MEDICAL L1 EFFECTS, corroborated: 'the first upgrade, will result in the healing cost going down by 10 percent and the chances of player injury also getting cut by 5 percent. Subsequent upgrades, of course, mean even cheaper healing costs and lower chances of players getting hurt.' And 'Maxing the Medical Centre will make individual and group physio trips super cheap essentially allowing you endless playtime with absolutely zero energy woes.' (3) THE COMMERCIAL L1 EFFECT: 'improve by 6 percent after the first upgrade' in bonus match winnings, with the 75-gem first upgrade 'added on top of the coins you already earn for playing a match'. (4) THE COMMERCIAL CENTRE ALSO GIVES SCOUT DISCOUNTS - a third source for its discount role: 'You can also get progressively higher kit and logo discounts, AS WELL AS SCOUT DISCOUNTS, by leveling up this building.' (5) THE COMMERCIAL NERF HISTORY, which explains C-019: 'In DLS20, DLS21 Commercials gived ~ 50% bonus coins per match if max it, now bonus is 10%, on maxed commercial' - and the current value is 'a bonus of 10 to 20 coins/match', against a 2021 source claiming '40-50 coins in every game when you become 5 stars'. So the figure has fallen across builds. (6) COMMERCIAL L3 REMOVES STADIUM RUST: 'Commercial is also good because the last level will remove all the rust from the stadium... To level 3 is enough to unrust your roof.' (7) THE SIX-FACILITY PRIORITY LIST, a complete ranked order: '1) Stadium Capacity 2) Training Facility 3) Accommodation Facility 4) Commercial Facility 5) Medical Facility 6) Recruitment Facility' - and the reasoning is the arithmetic: '1125 Diamonds being used on the commercial facility for a bonus of 10 to 20 coins/match is not worth it knowing you can max 2.5 players with the same amount of diamonds.' So 1,125 gems = 2.5 maxed players = about 450 gems per maxed player. (8) THE FANZONE HAS FIVE LEVELS - a second mod-site source ('Instantly level up your Commercial, Medical, Training, and the brand-new Fanzone facilities to level 5') agreeing with the wave-55 claim. (9) THE F2P COIN COST OF A MAXED PLAYER, the wave's most valuable figure: 'Common: 32,000 Coins (Average of 400 coins per player [80 coaches]) · Rare: 30,000 Coins (Average of 1,500 coins per player [20 coaches])', with 'Rare can cost as low as 1,460 (80 defender)'. So a free-to-play max costs roughly 30,000-32,000 coins in bought-and-released players - which is why the corpus's coin engine matters more than the gem engine for squad building. (10) LEGENDARY COACHES DO NOT RAISE THE UPGRADE CAP: 'Legendary coaches DO NOT increase the cap of upgrades at the end, I maxed my Son card with a legendary coach and it only upgraded 1 stat (it was +4 with a breakthrough).' (11) BREAKTHROUGHS MAY NOT ADD EXTRA STATS AT MAX: 'I have seen a few people that claim breakthroughs do add extra stats to players without adding additional progression in OVR during regular upgrading, but mine did not work this way when the card is ready to max out.' (12) THE SPECIAL-vs-NORMAL COACH EFFICIENCY CONFLICT: one source claims '26.25 gems/upgrade point for legendary special coach vs 5.8 gems/upgrade point for legendary normal coach'. The 26.25 figure is close to the derived 23.33 (280/12); the 5.8 figure has no derivation behind it and conflicts with the whole ladder. RECORDED AS AN UNSUPPORTED OUTLIER. (13) THE RECRUITMENT CENTRE'S FUNCTION, from a second source: 'reclutamiento reduce el costo de diamantes o monedas para agentes y ojeadores' - it reduces the GEM OR COIN cost of agents and scouts. (14) THE FACILITIES EMPIRE: you can 'view inside/outside' the stadium and 'toggle covered/uncovered' stands.",
    "evidence/raw/turn35_w76/EV-490_facility_ladder_and_f2p_max_cost.html",
    "FACILITY LADDER confirmed by a second source: 75/150/225/300/375 gems per level = 1,125 per facility, with ACCOMMODATION the exception at TEN levels (75-750 = 4,125 gems) because it is the only one with more than five. MEDICAL L1: -10% healing cost and -5% injury chance; maxed Medical makes physio trips 'super cheap' with 'endless playtime'. COMMERCIAL L1: +6% bonus match winnings, and it ALSO gives SCOUT DISCOUNTS on top of kit and logo discounts. COMMERCIAL NERF: DLS20/21 gave ~50% at max, now 10% (10-20 coins a match), against a 2021 claim of 40-50. COMMERCIAL L3 REMOVES STADIUM RUST. SIX-FACILITY PRIORITY: Stadium > Training > Accommodation > Commercial > Medical > Recruitment, on the arithmetic that 1,125 gems = 2.5 maxed players (~450 gems each). FANZONE: five levels (second mod-site source). F2P MAX COST: ~32,000 coins via Common coaches (80 x ~400) or ~30,000 via Rare (20 x ~1,500), with an 80-rated defender at ~1,460 coins. LEGENDARY COACHES DO NOT RAISE THE UPGRADE CAP. Breakthroughs may not add extra stats once a card is ready to max. RECRUITMENT reduces the gem OR coin cost of agents and scouts. Facilities Empire: view the stadium inside/outside and toggle covered/uncovered stands",
    quality="community")

add_claim("THE UNIFORM FACILITY COST LADDER, CONFIRMED BY A SECOND INDEPENDENT SOURCE: 75 / 150 / 225 / 300 / 375 gems for levels 1-5, so 1,125 gems per facility.", 3, "facilities/cost-ladder-second-source", [e_fac], notes="zfrglq and the Training Facility Guide agree exactly")
add_claim("Accommodation is the only facility with more than five levels - ten in total (75, 150, 225, 300, 375, 450, 525, 600, 675, 750 = 4,125 gems).", 2, "facilities/accommodation-only-ten-levels", [e_fac], notes="Corroborates the wave-55 Accommodation ladder")
add_claim("MEDICAL L1 EFFECTS, corroborated: healing cost down 10% and injury chance down 5%, with further reductions at each level. 'Maxing the Medical Centre will make individual and group physio trips super cheap essentially allowing you endless playtime with absolutely zero energy woes.'", 2, "facilities/medical-l1-effects", [e_fac])
add_claim("COMMERCIAL L1 gives +6% bonus match winnings on top of normal match coins, for the standard 75-gem first upgrade.", 3, "facilities/commercial-l1-plus-six-percent", [e_fac])
add_claim("THE COMMERCIAL CENTRE ALSO GIVES SCOUT DISCOUNTS: 'You can also get progressively higher kit and logo discounts, as well as SCOUT DISCOUNTS, by leveling up this building.'", 3, "facilities/commercial-also-discounts-scouts", [e_fac], notes="A third source for the Commercial's discount role")
add_claim("THE COMMERCIAL NERF HISTORY: 'In DLS20, DLS21 Commercials gived ~ 50% bonus coins per match if max it, now bonus is 10%, on maxed commercial' - and the current value is 'a bonus of 10 to 20 coins/match', against a 2021 source claiming '40-50 coins in every game when you become 5 stars'.", 3, "facilities/commercial-nerf-history", [e_fac], notes="Explains C-019's spread")
add_claim("COMMERCIAL L3 REMOVES STADIUM RUST: 'Commercial is also good because the last level will remove all the rust from the stadium... To level 3 is enough to unrust your roof.'", 3, "facilities/commercial-l3-removes-rust", [e_fac])
add_claim("THE SIX-FACILITY PRIORITY ORDER: 1 Stadium capacity, 2 Training, 3 Accommodation, 4 Commercial, 5 Medical, 6 Recruitment - on the arithmetic that '1125 Diamonds being used on the commercial facility for a bonus of 10 to 20 coins/match is not worth it knowing you can max 2.5 players with the same amount of diamonds.'", 3, "facilities/six-facility-priority-order", [e_fac])
add_claim("THE GEM-TO-PLAYER CONVERSION: 1,125 gems maxes about 2.5 players, i.e. roughly 450 gems per fully maxed player - the number that makes every facility decision comparable to a coaching decision.", 3, "economy/1125-gems-equals-2.5-players", [e_fac])
add_claim("THE FANZONE HAS FIVE LEVELS - a second mod-site source ('Instantly level up your Commercial, Medical, Training, and the brand-new Fanzone facilities to level 5') agreeing with the wave-55 claim. The per-level cost remains unpublished.", 3, "facilities/fanzone-five-levels-second-source", [e_fac])
add_claim("THE F2P COIN COST OF A MAXED PLAYER: ~32,000 coins via Common coaches (an average of 400 coins per player released, 80 coaches) or ~30,000 via Rare (20 coaches at ~1,500), with an 80-rated defender available at about 1,460 coins.", 2, "economy/coin-cost-to-max-a-player", [e_fac], notes="The number that decides whether an F2P player maxes a star or farms facilities")
add_claim("LEGENDARY COACHES DO NOT RAISE THE UPGRADE CAP: 'Legendary coaches DO NOT increase the cap of upgrades at the end, I maxed my Son card with a legendary coach and it only upgraded 1 stat (it was +4 with a breakthrough).'", 3, "coaching/legendary-does-not-raise-cap", [e_fac], notes="Corrects a common belief")
add_claim("Breakthroughs may not add extra stats once a card is ready to max: 'I have seen a few people that claim breakthroughs do add extra stats to players without adding additional progression in OVR during regular upgrading, but mine did not work this way when the card is ready to max out.'", 3, "coaching/breakthroughs-at-max", [e_fac])
add_claim("CONFLICT - the special-vs-normal coach efficiency: one source claims '26.25 gems/upgrade point for legendary special coach vs 5.8 gems/upgrade point for legendary normal coach'. The 26.25 figure is close to the derived 23.33 (280/12); the 5.8 figure has no derivation and conflicts with the entire ladder. RECORDED AS AN UNSUPPORTED OUTLIER.", 3, "coaching/special-vs-normal-efficiency-conflict", [e_fac])
add_claim("THE RECRUITMENT CENTRE'S FUNCTION, from a second source: it reduces the GEM OR COIN cost of agents and scouts.", 3, "facilities/recruitment-reduces-gem-or-coin-cost", [e_fac])
add_claim("THE FACILITIES EMPIRE: the stadium can be viewed inside and outside, and stands can be toggled covered or uncovered.", 2, "stadium/view-inside-outside-covered-toggle", [e_fac])

for name in ('EV-490_facility_ladder_and_f2p_max_cost.html',):
    p=os.path.join(RAW_DIR,name)
    if not os.path.exists(p):
        with open(p,'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f"Added {cl_id-(last_cl+1)} new claims and {ev_id-(last_ev+1)} EVs. Totals: {n_cl} claims, {n_ev} EVs")
